"""Score the screenshots generated by ui-accuracy.mjs against DOM text/rects."""
import json
import subprocess
import unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = Path('/private/tmp/mac-ocr-ui-accuracy')

def norm(text):
    return ' '.join(unicodedata.normalize('NFC', text).split())

def distance(a, b):
    row = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        nxt = [i]
        for j, y in enumerate(b, 1):
            nxt.append(min(nxt[-1]+1, row[j]+1, row[j-1]+(x != y)))
        row = nxt
    return row[-1]

results = []
for sample in json.loads((OUT/'references.json').read_text()):
    run = subprocess.run([str(ROOT/'.build/release/mac-ocr'), str(OUT/f'{sample["name"]}.png'),
                          '--lang', 'vi-VN,en-US', '--level', 'accurate', '--pixels'],
                         capture_output=True, text=True, check=True, timeout=90)
    ocr = json.loads(run.stdout)
    (OUT/f'{sample["name"]}.ocr.json').write_text(run.stdout)
    checks = []
    for label in sample['labels']:
        expected = norm(label['text'])
        lines = ocr['lines']
        best = min(lines, key=lambda l: 0 if expected in norm(l['text']) else distance(expected, norm(l['text'])), default=None)
        observed = norm(best['text']) if best else ''
        exact = expected in observed
        error = 0 if exact else distance(expected, observed)
        center_inside = None
        if best and expected == observed:
            box = best['box']
            x = (box['x'] + box['width']/2) * sample['width'] / ocr['width']
            y = (box['y'] + box['height']/2) * sample['height'] / ocr['height']
            center_inside = label['x']-3 <= x <= label['x']+label['width']+3 and label['y']-3 <= y <= label['y']+label['height']+3
        checks.append({'expected':expected, 'observed':observed, 'exact':exact, 'edits':error,
                       'characters':len(expected), 'centerInside':center_inside})
    result = {'name':sample['name'], 'imageWidth':ocr['width'], 'imageHeight':ocr['height'], 'labels':len(checks), 'exact':sum(c['exact'] for c in checks),
              'characterErrorRate':sum(c['edits'] for c in checks)/sum(c['characters'] for c in checks),
              'coordinateChecks':sum(c['centerInside'] is not None for c in checks),
              'coordinatePass':sum(c['centerInside'] is True for c in checks), 'checks':checks}
    results.append(result)
    print(f'{result["name"]:18} labels={result["exact"]}/{result["labels"]} labelCER={result["characterErrorRate"]:.2%} centers={result["coordinatePass"]}/{result["coordinateChecks"]}', flush=True)
(OUT/'results.json').write_text(json.dumps(results, ensure_ascii=False, indent=2))
